<script setup>
import {ref,onMounted} from 'vue';import {api} from '../api';import Pagination from '../components/Pagination.vue';import GridSearch from '../components/GridSearch.vue';import {useGrid} from '../composables/useGrid';
const rows=ref([]),docs=ref([]),patients=ref([]),show=ref(false),f=ref(blank()),err=ref('');const {search,page,pageCount,pagedRows,sortedRows,sortBy,sortIndicator}=useGrid(rows,10);
function blank(){return{patientId:null,externalPatientName:'',externalPatientPhone:'',doctorId:null,otRoom:'OT 1',startAtUtc:'',endAtUtc:'',procedureName:'',doctorPayoutAmount:0};}
async function load(){const [r,d,p]=await Promise.all([api.get('/ot'),api.get('/doctors'),api.get('/patients')]);rows.value=r.data;docs.value=d.data;patients.value=p.data;}function add(){f.value=blank();err.value='';show.value=true;}async function save(){try{err.value='';await api.post('/ot',f.value);show.value=false;await load();}catch(e){err.value=e.response?.data?.message||'Unable to book OT';}}onMounted(load);
</script>
<template><h1>OT Management</h1><div class="toolbar"><button @click="add">+ Book OT</button></div><GridSearch v-model="search" placeholder="Search OT booking, room, doctor, patient, procedure..."/><table class="table"><tr><th>Booking</th><th>OT</th><th>Doctor</th><th>Start</th><th>End</th><th>Procedure</th><th>Doctor Payout</th><th>Status</th></tr><tr v-for="x in pagedRows" :key="x.id"><td>{{x.bookingNumber}}</td><td>{{x.otRoom}}</td><td>{{x.doctorName}}</td><td>{{new Date(x.startAtUtc).toLocaleString()}}</td><td>{{new Date(x.endAtUtc).toLocaleString()}}</td><td>{{x.procedureName}}</td><td>₹{{Number(x.doctorPayoutAmount||0).toFixed(2)}}</td><td>{{x.status}}</td></tr></table><Pagination :page="page" :page-count="pageCount" :total="sortedRows.length" :page-size="10" @update:page="page=$event" />
<div v-if="show" class="modal-bg"><div class="modal"><button class="modal-close-x" @click="show=false">×</button><h2>Book OT</h2><div class="form-grid"><label>Existing Patient<select v-model.number="f.patientId"><option :value="null">Outside Patient</option><option v-for="p in patients" :value="p.id">{{p.name}} - {{p.patientCode}}</option></select></label><label>Doctor<select v-model.number="f.doctorId"><option :value="null">Select Doctor</option><option v-for="d in docs" :value="d.id">{{d.name}}</option></select></label><label v-if="!f.patientId">Outside Patient Name<input v-model="f.externalPatientName"></label><label v-if="!f.patientId">Phone<input v-model="f.externalPatientPhone"></label><label>OT<select v-model="f.otRoom"><option>OT 1</option><option>OT 2</option></select></label><label>Procedure<input v-model="f.procedureName"></label><label>Start<input type="datetime-local" v-model="f.startAtUtc"></label><label>End<input type="datetime-local" v-model="f.endAtUtc"></label><label>Doctor OT Payout ₹<input type="number" min="0" step="0.01" v-model.number="f.doctorPayoutAmount"></label></div><div class="danger">{{err}}</div><div class="modal-actions"><button @click="save">Book</button><button class="secondary" @click="show=false">Cancel</button></div></div></div></template>
